CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_eficiencia_atletas`  AS SELECT `a`.`IdAtleta` AS `IdAtleta`, `a`.`Nome` AS `Nome`, `a`.`NumeroCamisola` AS `NumeroCamisola`, `a`.`Posicao` AS `Posicao`, `a`.`Escalao` AS `Escalao`, count(distinct `ev`.`IdJogo`) AS `JogosComRegisto`, sum(case when `ev`.`TipoEvento` in ('Golo','Golo 7m') then 1 else 0 end) AS `Golos`, sum(case when `ev`.`TipoEvento` in ('Golo','Remate','Remate Falhado','Remate Defendido','Remate ao Poste','Golo 7m','7m Falhado','7m Defendido') then 1 else 0 end) AS `Remates`, sum(case when `ev`.`TipoEvento` = 'Remate Falhado' then 1 else 0 end) AS `RematesFalhados`, sum(case when `ev`.`TipoEvento` = 'Remate Defendido' then 1 else 0 end) AS `RematesDefendidos`, sum(case when `ev`.`TipoEvento` = 'Remate ao Poste' then 1 else 0 end) AS `RematesPoste`, round(sum(case when `ev`.`TipoEvento` in ('Golo','Golo 7m') then 1 else 0 end) / nullif(sum(case when `ev`.`TipoEvento` in ('Golo','Remate','Remate Falhado','Remate Defendido','Remate ao Poste','Golo 7m','7m Falhado','7m Defendido') then 1 else 0 end),0) * 100,2) AS `EficaciaRemate`, sum(case when `ev`.`TipoEvento` = 'Golo 7m' then 1 else 0 end) AS `Golos7m`, sum(case when `ev`.`TipoEvento` in ('Golo 7m','7m Falhado','7m Defendido') then 1 else 0 end) AS `Remates7m`, round(sum(case when `ev`.`TipoEvento` = 'Golo 7m' then 1 else 0 end) / nullif(sum(case when `ev`.`TipoEvento` in ('Golo 7m','7m Falhado','7m Defendido') then 1 else 0 end),0) * 100,2) AS `Eficacia7m`, sum(case when `ev`.`TipoEvento` = 'Assistencia' then 1 else 0 end) AS `Assistencias`, sum(case when `ev`.`TipoEvento` = 'Recuperacao' then 1 else 0 end) AS `Recuperacoes`, sum(case when `ev`.`TipoEvento` = 'Perda de Bola' then 1 else 0 end) AS `PerdasBola`, sum(case when `ev`.`TipoEvento` = 'Falta' then 1 else 0 end) AS `Faltas`, sum(case when `ev`.`TipoEvento` = 'Exclusao 2 Min' then 1 else 0 end) AS `Exclusoes2Min`, sum(case when `ev`.`TipoEvento` = 'Cartao Amarelo' then 1 else 0 end) AS `CartoesAmarelos`, sum(case when `ev`.`TipoEvento` = 'Cartao Vermelho' then 1 else 0 end) AS `CartoesVermelhos`, sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m') then 1 else 0 end) AS `Defesas`, sum(case when `ev`.`TipoEvento` = 'Defesa 7m' then 1 else 0 end) AS `Defesas7m`, sum(case when `ev`.`TipoEvento` = 'Golo Sofrido' then 1 else 0 end) AS `GolosSofridos`, sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m','Golo Sofrido') then 1 else 0 end) AS `RematesEnfrentados`, round(sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m') then 1 else 0 end) / nullif(sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m','Golo Sofrido') then 1 else 0 end),0) * 100,2) AS `EficaciaGuardaRedes` FROM (`atletas` `a` left join `eventos_jogo` `ev` on(`ev`.`IdAtleta` = `a`.`IdAtleta`)) GROUP BY `a`.`IdAtleta`, `a`.`Nome`, `a`.`NumeroCamisola`, `a`.`Posicao`, `a`.`Escalao` ;

