' then 1 else 0 end) AS `Exclusoes2Min`, sum(case when `ev`.`TipoEvento` = 'Cartao Amarelo' then 1 else 0 end) AS `CartoesAmarelos`, sum(case when `ev`.`TipoEvento` = 'Cartao Vermelho' then 1 else 0 end) AS `CartoesVermelhos`, sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m') then 1 else 0 end) AS `Defesas`, sum(case when `ev`.`TipoEvento` = 'Defesa 7m' then 1 else 0 end) AS `Defesas7m`, sum(case when `ev`.`TipoEvento` = 'Golo Sofrido' then 1 else 0 end) AS `GolosSofridos`, sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m','Golo Sofrido') then 1 else 0 end) AS `RematesEnfrentados`, round(sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m') then 1 else 0 end) / nullif(sum(case when `ev`.`TipoEvento` in ('Defesa','Defesa 7m','Golo Sofrido') then 1 else 0 end),0) * 100,2) AS `EficaciaGuardaRedes` FROM ((`atletas` `a` join `eventos_jogo` `ev` on(`ev`.`IdAtleta` = `a`.`IdAtleta`)) join `jogos` `j` on(`j`.`IdJogo` = `ev`.`IdJogo`)) GROUP BY `a`.`IdAtleta`, `a`.`Nome`, `a`.`NumeroCamisola`, `a`.`Posicao`, `j`.`IdJogo`, `j`.`DataJogo`, `j`.`Adversario`, `j`.`CasaFora` ;

