UPDATE atletas SET Nacionalidade='Portugal' WHERE Nacionalidade IS NULL OR TRIM(Nacionalidade)='';
UPDATE atletas SET DataNasc=DATE_ADD('1997-01-01', INTERVAL MOD(IdAtleta*173,4018) DAY) WHERE DataNasc IS NULL;
UPDATE atletas SET Posicao=CASE MOD(IdAtleta,7) WHEN 0 THEN 'GR' WHEN 1 THEN 'P' WHEN 2 THEN 'L' WHEN 3 THEN 'C' WHEN 4 THEN 'PV' WHEN 5 THEN 'P' ELSE 'L' END WHERE Posicao IS NULL;
UPDATE atletas SET MaoDominante=CASE WHEN Posicao IN ('PD','LD') THEN 'Esquerda' ELSE 'Direita' END WHERE MaoDominante IS NULL;
UPDATE atletas SET Altura=ROUND(CASE WHEN Sexo='F' THEN 1.62+MOD(IdAtleta*11,27)/100 ELSE 1.74+MOD(IdAtleta*13,27)/100 END,2) WHERE Altura IS NULL OR Altura<=0;
UPDATE atletas SET Peso=ROUND(Altura*Altura*CASE WHEN Sexo='F' THEN 22.8 ELSE 24.8 END,1) WHERE Peso IS NULL OR Peso<=0;
UPDATE atletas SET NumeroCamisola=2+MOD(IdAtleta*11,96) WHERE NumeroCamisola IS NULL;
UPDATE atletas SET Foto=CONCAT('assets/atletas/atleta_',LPAD(IdAtleta,4,'0'),'.svg') WHERE Foto IS NULL OR TRIM(Foto)='';
UPDATE atletas SET OrigemPerfil='Simulado',FontePerfil='Dados de demonstração da PAP; sem fonte pública individual suficiente.',PerfilAtualizadoEm='2026-09-22' WHERE OrigemPerfil='Por verificar';

-- Verificação final: todos estes campos devem ficar a 0 em falta.
SELECT COUNT(*) AS TotalAtletas, SUM(Nacionalidade IS NULL OR TRIM(Nacionalidade)='') AS FaltaNacionalidade, SUM(DataNasc IS NULL) AS FaltaNascimento, SUM(Altura IS NULL OR Altura<=0) AS FaltaAltura, SUM(Peso IS NULL OR Peso<=0) AS FaltaPeso, SUM(MaoDominante IS NULL) AS FaltaMao, SUM(Posicao IS NULL) AS FaltaPosicao, SUM(NumeroCamisola IS NULL) AS FaltaCamisola, SUM(Foto IS NULL OR TRIM(Foto)='') AS FaltaFoto FROM atletas;
COMMIT;
